"""SQLite storage. The database file is created and seeded on first start."""

from __future__ import annotations

import sqlite3
import threading

SCHEMA = """
CREATE TABLE IF NOT EXISTS products (
    sku TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    price REAL NOT NULL,
    category TEXT NOT NULL,
    active INTEGER NOT NULL DEFAULT 1,
    sort_order INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS promo_codes (
    code TEXT PRIMARY KEY,
    percent_off REAL,
    amount_off REAL,
    active INTEGER NOT NULL DEFAULT 1
);
CREATE TABLE IF NOT EXISTS orders (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    created_at TEXT NOT NULL,
    customer_name TEXT NOT NULL,
    customer_email TEXT NOT NULL,
    customer_phone TEXT NOT NULL DEFAULT '',
    pickup_date TEXT NOT NULL,
    promo_code TEXT,
    subtotal REAL NOT NULL,
    discount REAL NOT NULL,
    tax REAL NOT NULL,
    total REAL NOT NULL,
    status TEXT NOT NULL DEFAULT 'placed'
);
CREATE TABLE IF NOT EXISTS order_items (
    order_id INTEGER NOT NULL REFERENCES orders(id),
    sku TEXT NOT NULL,
    name TEXT NOT NULL,
    qty INTEGER NOT NULL,
    unit_price REAL NOT NULL,
    line_total REAL NOT NULL
);
"""

PRODUCTS = [
    ("BREAD9", "Sourdough Loaf", 9.00, "Bread", 1),
    ("BAGUETTE5", "Baguette", 5.00, "Bread", 2),
    ("BAGEL225", "Everything Bagel", 2.25, "Bread", 3),
    ("CROISSANT21", "Croissant Box (6)", 21.00, "Pastry", 4),
    ("CINNAMON325", "Cinnamon Roll", 3.25, "Pastry", 5),
    ("SCONE375", "Blueberry Scone", 3.75, "Pastry", 6),
    ("COOKIE12", "Cookie Box (12)", 12.00, "Pastry", 7),
    ("PIE32", "Seasonal Pie", 32.00, "Cakes & Pies", 8),
    ("CAKE48", "Birthday Cake", 48.00, "Cakes & Pies", 9),
    ("CATER120", "Catering Tray", 120.00, "Catering", 10),
    ("COFFEE18", "Coffee Beans 1lb", 18.00, "Pantry", 11),
    ("GIFT25", "$25 Gift Card", 25.00, "Gift Cards", 12),
]
PROMO_CODES = [
    ("WELCOME10", 10.0, None),
    ("FALL15", 15.0, None),
    ("FIVEOFF", None, 5.0),
]

_lock = threading.RLock()


class CapacityError(Exception):
    def __init__(self, message, **details):
        super().__init__(message)
        self.details = details


class Database:
    def __init__(self, path: str):
        self.path = path
        self.conn = sqlite3.connect(path, check_same_thread=False)
        self.conn.row_factory = sqlite3.Row
        with _lock:
            self.conn.executescript(SCHEMA)
            if not self.conn.execute("SELECT 1 FROM products LIMIT 1").fetchone():
                self.conn.executemany(
                    "INSERT INTO products (sku, name, price, category, sort_order) VALUES (?, ?, ?, ?, ?)", PRODUCTS)
                self.conn.executemany(
                    "INSERT INTO promo_codes (code, percent_off, amount_off) VALUES (?, ?, ?)", PROMO_CODES)
            product_columns = {r['name'] for r in self.conn.execute('PRAGMA table_info(products)')}
            if 'daily_limit' not in product_columns:
                self.conn.execute('ALTER TABLE products ADD COLUMN daily_limit INTEGER')
                self.conn.executemany('UPDATE products SET daily_limit = ? WHERE sku = ?',
                                      [(6, 'CAKE48'), (4, 'CATER120'), (8, 'PIE32')])
            order_columns = {r['name'] for r in self.conn.execute('PRAGMA table_info(orders)')}
            if 'pickup_slot' not in order_columns:
                self.conn.execute('ALTER TABLE orders ADD COLUMN pickup_slot TEXT')
            self.conn.commit()

    def query(self, sql: str, params=()) -> list:
        with _lock:
            return self.conn.execute(sql, params).fetchall()

    def products(self, active_only: bool = True) -> list:
        where = "WHERE active = 1" if active_only else ""
        return self.query(f"SELECT * FROM products {where} ORDER BY sort_order")

    def product(self, sku: str):
        rows = self.query("SELECT * FROM products WHERE sku = ?", (sku,))
        return rows[0] if rows else None

    def promo(self, code: str):
        rows = self.query("SELECT * FROM promo_codes WHERE code = ? AND active = 1", (code.strip().upper(),))
        return rows[0] if rows else None

    def insert_order(self, order: dict, items: list) -> int:
        with _lock:
            try:
                self.conn.execute('BEGIN IMMEDIATE')
                counts = self.slot_counts(order['pickup_date'])
                if counts.get(order['pickup_slot'], 0) >= 4:
                    raise CapacityError('That pickup time is full. Please choose another time.')
                quantities = {}
                for item in items:
                    quantities[item['sku']] = quantities.get(item['sku'], 0) + item['qty']
                for sku, qty in quantities.items():
                    limit = self.product(sku)['daily_limit']
                    if limit is not None:
                        remaining = max(0, limit - self.sold_quantity(sku, order['pickup_date']))
                        if qty > remaining:
                            raise CapacityError('Not enough of this item left for that date.',
                                                sku=sku, remaining=remaining)
                cursor = self.conn.execute(
                    "INSERT INTO orders (created_at, customer_name, customer_email, customer_phone, pickup_date, "
                    "pickup_slot, promo_code, subtotal, discount, tax, total) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                    (order["created_at"], order["customer_name"], order["customer_email"], order["customer_phone"],
                     order["pickup_date"], order['pickup_slot'], order["promo_code"], order["subtotal"],
                     order["discount"], order["tax"], order["total"]))
                order_id = cursor.lastrowid
                self.conn.executemany(
                    "INSERT INTO order_items (order_id, sku, name, qty, unit_price, line_total) VALUES (?, ?, ?, ?, ?, ?, ?)",
                    [(order_id, i["sku"], i["name"], i["qty"], i["unit_price"], i["line_total"]) for i in items])
                self.conn.commit()
                return order_id
            except Exception:
                self.conn.rollback()
                raise

    def slot_counts(self, pickup_date):
        return {r['pickup_slot']: r['n'] for r in self.query(
            "SELECT pickup_slot, COUNT(*) AS n FROM orders WHERE pickup_date = ? "
            "AND status != 'cancelled' GROUP BY pickup_slot", (pickup_date,))}

    def sold_quantity(self, sku, pickup_date):
        return self.query(
            "SELECT COALESCE(SUM(i.qty), 0) AS n FROM order_items i JOIN orders o ON o.id = i.order_id "
            "WHERE i.sku = ? AND o.pickup_date = ? AND o.status != 'cancelled'", (sku, pickup_date))[0]['n']

    def menu(self, pickup_date=None):
        with _lock:
            products = []
            for row in self.products():
                p = {key: row[key] for key in ('sku', 'name', 'price', 'category', 'daily_limit')}
                if pickup_date is not None:
                    p['remaining'] = (None if p['daily_limit'] is None else
                                      max(0, p['daily_limit'] - self.sold_quantity(p['sku'], pickup_date)))
                    p['sold_out'] = p['remaining'] == 0
                products.append(p)
            return products

    def set_limit(self, sku, limit):
        with _lock, self.conn:
            self.conn.execute('UPDATE products SET daily_limit = ? WHERE sku = ?', (limit, sku))

    def order(self, order_id: int):
        rows = self.query("SELECT * FROM orders WHERE id = ?", (order_id,))
        return rows[0] if rows else None

    def order_items(self, order_id: int) -> list:
        return self.query("SELECT * FROM order_items WHERE order_id = ? ORDER BY rowid", (order_id,))

    def orders(self, pickup_date: str | None = None) -> list:
        if pickup_date:
            return self.query("SELECT * FROM orders WHERE pickup_date = ? ORDER BY pickup_slot, id", (pickup_date,))
        return self.query("SELECT * FROM orders ORDER BY pickup_date, pickup_slot, id")

    def set_status(self, order_id: int, status: str) -> None:
        with _lock:
            self.conn.execute("UPDATE orders SET status = ? WHERE id = ?", (status, order_id))
            self.conn.commit()

    def require_admin(self) -> bool:
        if self.is_admin():
            return True
        self.send(401, b"Admin login required", "text/plain",
                  {"WWW-Authenticate": 'Basic realm="Corner Loaf admin"'})
        return False

    # --- routing --------------------------------------------------------------------------------
    def do_GET(self):
        url = urlparse(self.path)
        query = {k: v[0] for k, v in parse_qs(url.query).items()}
        path = url.path
        if path == "/":
            try:
                return self.menu_page(query.get('date'))
            except ValidationError as exc:
                return self.send_json(400, {'error': str(exc)})
        if path == "/checkout":
            return self.send_html(200, render("checkout.html", title="Checkout"))
        if match := re.fullmatch(r"/order/(\d+)", path):
            return self.confirmation_page(int(match[1]))
        if path in ('/api/menu', '/api/slots'):
            try:
                if path == '/api/slots':
                    return self.send_json(200, slots_json(self.db, query.get('date')))
                date = query.get('date')
                if date is not None:
                    parse_date(date)
                return self.send_json(200, {'products': self.db.menu(date)})
            except ValidationError as exc:
                return self.send_json(400, {'error': str(exc)})
        if match := re.fullmatch(r"/api/orders/(\d+)", path):
            row = self.db.order(int(match[1]))
            return self.send_json(200, order_json(self.db, row)) if row else self.not_found()
        if path == "/admin":
            return self.require_admin() and self.admin_page(query.get("date"))
        if path == "/admin/api/orders":
            if self.require_admin():
                self.send_json(200, {"orders": [order_json(self.db, r) for r in self.db.orders(query.get("date"))]})
            return
        if path.startswith("/static/"):
            return self.static(path[len("/static/"):])
        self.not_found()

    def do_POST(self):
        path = urlparse(self.path).path
        try:
            if path == "/api/orders":
                order_id = create_order(self.db, self.read_json())
                return self.send_json(201, order_json(self.db, self.db.order(order_id)))
            if match := re.fullmatch(r"/admin/api/orders/(\d+)/cancel", path):
                if not self.require_admin():
                    return
                row = self.db.order(int(match[1]))
                if row is None:
                    return self.not_found()
                self.db.set_status(row["id"], "cancelled")
                return self.send_json(200, order_json(self.db, self.db.order(row["id"])))
        except CapacityError as exc:
            return self.send_json(409, {'error': str(exc), **exc.details})
        except ValidationError as exc:
            return self.send_json(400, {"error": str(exc)})
        self.not_found()

    def do_PUT(self):
        path = urlparse(self.path).path
        if match := re.fullmatch(r'/admin/api/products/([^/]+)', path):
            if not self.require_admin():
                return
            product = self.db.product(match[1])
            if product is None:
                return self.not_found()
            try:
                payload = self.read_json()
                if not isinstance(payload, dict) or 'daily_limit' not in payload:
                    raise ValidationError('Please provide daily_limit')
                limit = payload['daily_limit']
                if limit is not None and (type(limit) is not int or limit < 0):
                    raise ValidationError('Daily limit must be a nonnegative whole number or null')
                self.db.set_limit(product['sku'], limit)
                updated = self.db.product(product['sku'])
                return self.send_json(200, {k: updated[k] for k in
                                           ('sku', 'name', 'price', 'category', 'daily_limit')})
            except ValidationError as exc:
                return self.send_json(400, {'error': str(exc)})
        self.not_found()

    # --- pages ----------------------------------------------------------------------------------
    def menu_page(self, date=None):
        if date is not None:
            parse_date(date)
        sections, current = [], None
        for product in self.db.menu(date):
            if product["category"] != current:
                if current is not None:
                    sections.append("</ul></section>")
                current = product["category"]
                sections.append(f"<section><h2>{html.escape(current)}</h2><ul class=\"menu\">")
            sold_out = product.get('sold_out', False)
            sold_attr = ' data-sold-out="true"' if sold_out else ''
            disabled = ' disabled' if sold_out else ''
            label = 'Sold out' if sold_out else 'Add'
            sections.append(
                f"<li class=\"item\" data-sku=\"{product['sku']}\"{sold_attr}>"
                f"<span class=\"name\">{html.escape(product['name'])}</span>"
                f"<span class=\"price\">{money(product['price'])}</span>"
                f"<button type=\"button\" class=\"add\" data-sku=\"{product['sku']}\" "
                f"data-name=\"{html.escape(product['name'])}\" data-price=\"{product['price']}\"{disabled}>{label}</button></li>")
        if current is not None:
            sections.append("</ul></section>")
        self.send_html(200, render("menu.html", title="Order online", menu="\n".join(sections), date=html.escape(date or "")))

    def confirmation_page(self, order_id: int):
        row = self.db.order(order_id)
        if row is None:
            return self.not_found()
        order = order_json(self.db, row)
        items = "\n".join(f"<tr><td>{i['qty']} × {html.escape(i['name'])}</td><td>{money(i['line_total'])}</td></tr>"
                          for i in order["items"])
        self.send_html(200, render(
            "confirmation.html", title=f"Order #{order_id}", order_id=order_id,
            name=html.escape(order["customer"]["name"]), pickup_date=order["pickup_date"], pickup_slot=order["pickup_slot"] or "Time not assigned", items=items,
            subtotal=money(order["subtotal"]), discount=money(order["discount"]), tax=money(order["tax"]),
            total=money(order["total"]), status=order["status"]))

    def admin_page(self, pickup_date: str | None):
        rows = []
        for row in self.db.orders(pickup_date):
            order = order_json(self.db, row)
            items = ", ".join(f"{i['qty']} × {html.escape(i['name'])}" for i in order["items"])
            rows.append(
                f"<tr data-order-id=\"{order['id']}\" class=\"{order['status']}\"><td>#{order['id']}</td>"
                f"<td>{order['pickup_date']}<br>{order['pickup_slot'] or 'Time not assigned'}</td><td>{html.escape(order['customer']['name'])}<br>"
                f"<small>{html.escape(order['customer']['phone'])}</small></td><td>{items}</td>"
                f"<td>{money(order['total'])}</td><td>{order['status']}</td></tr>")
        self.send_html(200, render("admin.html", title="Orders", date=html.escape(pickup_date or ""),
                                   rows="\n".join(rows) or "<tr><td colspan=\"6\">No orders</td></tr>",
                                   products=json.dumps(self.db.menu()).replace("<", "\\u003c")))

    def static(self, name: str):
        target = (STATIC / name).resolve()
        if STATIC not in target.parents or not target.is_file():
            return self.not_found()
        types = {".css": "text/css", ".js": "application/javascript"}
        self.send(200, target.read_bytes(), types.get(target.suffix, "application/octet-stream"))


def make_server(port: int, db_path: str, host: str = "127.0.0.1") -> ThreadingHTTPServer:
    Path(db_path).parent.mkdir(parents=True, exist_ok=True)
    handler = type("BoundHandler", (Handler,), {
        "db": Database(db_path), "admin_password": os.environ.get("ADMIN_PASSWORD", "flour")})
    return ThreadingHTTPServer((host, port), handler)


def main() -> None:
    parser = argparse.ArgumentParser(description="Corner Loaf Bakery ordering site")
    parser.add_argument("--port", type=int, default=8000)
    parser.add_argument("--host", default="127.0.0.1")
    parser.add_argument("--db", default="data/bakery.db")
    args = parser.parse_args()
    server = make_server(args.port, args.db, args.host)
    print(f"Corner Loaf ordering site on http://{args.host}:{server.server_port}", flush=True)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass


if __name__ == "__main__":
    main()

